const repo = "/tmp/issue-6-s4/live/flow-land-scratch";
const [doctor, local, issue, contract] = await Promise.all([
  tools.mcp__flow_delegate__delegation_doctor({cwd: repo}),
  tools.exec_command({
    cmd: "pwd -P && git -C /tmp/issue-6-s4/live/flow-land-scratch rev-parse --show-toplevel --git-common-dir && git -C /tmp/issue-6-s4/live/flow-land-scratch remote -v && git -C /tmp/issue-6-s4/live/flow-land-scratch status --short --branch && git -C /tmp/issue-6-s4/live/flow-land-scratch worktree list --porcelain",
    shell: "/bin/bash",
    login: false,
    workdir: "/tmp/issue-6-s4/live",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "gh issue view 3 --json number,state,title,body,labels,assignees,url,updatedAt",
    shell: "/bin/bash",
    login: false,
    workdir: repo,
    yield_time_ms: 10000,
    max_output_tokens: 30000
  }),
  tools.exec_command({
    cmd: "wc -l /home/jakub/.codex/plugins/cache/jakub/flow/0.29.0/seat-contract.md && sed -n '1,260p' /home/jakub/.codex/plugins/cache/jakub/flow/0.29.0/seat-contract.md",
    shell: "/bin/bash",
    login: false,
    workdir: "/tmp/issue-6-s4/live",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  })
]);
text(`--- doctor ---`);
if (doctor?.content) doctor.content.forEach(x => x.type === "text" ? text(x.text) : undefined);
else text(doctor);
text(`--- local ---\n${local.output}`);
text(`--- issue ---\n${issue.output}\nexit=${issue.exit_code}`);
text(`--- contract ---\n${contract.output}`);

